/**
 * Local preview renderer for the Mitten theme.
 *
 * Renders the REAL theme files (../theme) with liquidjs and mock store data
 * (catalog.json, generated by data/catalog.py) into ./dist so the design can be
 * reviewed without a Shopify store. It approximates Shopify Liquid: Shopify-only
 * tags/filters are shimmed below. For true fidelity use `shopify theme dev`.
 *
 *   npm install && npm run build   ->   open dist/index.html
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { Liquid, Tag } from 'liquidjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const THEME = path.resolve(HERE, '../theme');
const DIST = path.join(HERE, 'dist');
const read = (p) => fs.readFileSync(path.join(THEME, p), 'utf8');
const locale = JSON.parse(read('locales/en.default.json'));
const catalog = JSON.parse(fs.readFileSync(path.join(HERE, 'catalog.json'), 'utf8'));

/* ---------------- helpers ---------------- */
const kw = (args) => Object.fromEntries(args.filter(Array.isArray));
const pos = (args) => args.filter((a) => !Array.isArray(a));
const moneyFmt = (c) => '$' + (Number(c || 0) / 100).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
const hexToRgb = (h) => { h = String(h).replace('#', ''); return [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16)); };
const rgbToHex = (r) => '#' + r.map((v) => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, '0')).join('');
const schemaOf = (src) => { const m = src.match(/\{%-?\s*schema\s*-?%\}([\s\S]*?)\{%-?\s*endschema\s*-?%\}/); return m ? JSON.parse(m[1]) : {}; };

const PAGE_MAP = {
  'shopify://collections/gift-boxes': 'collection.html',
  'shopify://pages/build-a-box': 'build-a-box.html',
  'shopify://pages/corporate-gifts': 'corporate.html',
  'shopify://pages/about': '#',
};
const fixUrl = (v) => (typeof v === 'string' && v.startsWith('shopify://') ? PAGE_MAP[v] || '#' : v);

/* Product art: an illustrated "package" so the preview isn't a wall of grey placeholders. */
function art(p, w = 800) {
  const name = p.title.split(',')[0].replace(/&/g, '&amp;').replace(/'/g, '&#39;');
  const words = name.split(' ');
  const lines = []; let cur = '';
  for (const wd of words) { if ((cur + ' ' + wd).trim().length > 16) { lines.push(cur.trim()); cur = wd; } else cur += ' ' + wd; }
  lines.push(cur.trim());
  const isBox = p.kind === 'box';
  const pkg = isBox
    ? `<rect x="150" y="260" width="500" height="330" rx="18" fill="#C9A47A"/><rect x="130" y="230" width="540" height="70" rx="14" fill="#B58D63"/><rect x="380" y="230" width="40" height="360" fill="#B8352B"/><path d="M400 232c-60-70-150-40-110 0zM400 232c60-70 150-40 110 0z" fill="#B8352B"/>`
    : `<path d="M230 170h340l-20 470H250z" fill="#FBF8F1" stroke="#1F2D5C" stroke-width="6" stroke-linejoin="round"/><path d="M230 170q170-40 340 0" fill="none" stroke="#1F2D5C" stroke-width="6"/>`;
  const label = lines.slice(0, 3).map((l, i) => `<text x="400" y="${(isBox ? 680 : 520) + i * 34}" text-anchor="middle" font-family="Georgia,serif" font-weight="700" font-size="30" fill="#1F2D5C">${l}</text>`).join('');
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 800"><rect width="800" height="800" fill="${p.bg}"/><circle cx="660" cy="130" r="80" fill="#fff" opacity=".35"/>${pkg}<text x="400" y="${isBox ? 470 : 400}" text-anchor="middle" font-size="${isBox ? 150 : 170}">${p.emoji}</text>${label}<text x="400" y="770" text-anchor="middle" font-family="monospace" font-size="20" letter-spacing="4" fill="#1F2D5C" opacity=".6">${(p.vendor || '').toUpperCase().replace(/&/g, '&amp;')}</text></svg>`;
  return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
}

/* ---------------- mock objects ---------------- */
let vid = 1000;
const mf = (v) => (v ? { value: v } : { value: null });
function toProduct(p, i) {
  const media = { id: 5000 + i, src: art(p), alt: p.title, width: 800, height: 800 };
  const variant = { id: ++vid, price: p.price, compare_at_price: p.compare_at, available: true, title: 'Default Title', featured_media: media, options: ['Default Title'] };
  return {
    id: 100 + i, handle: p.handle, title: p.title, url: (p.kind === 'box' ? 'product.html' : 'product-item.html'),
    price: p.price, price_min: p.price, price_varies: false, available: true, tags: p.tags, vendor: p.vendor,
    description: `<p>${p.why}</p>`, featured_media: media, media: [media], has_only_default_variant: true,
    selected_or_first_available_variant: variant, variants: [variant], options_with_values: [],
    metafields: {
      custom: { region: mf(p.region), origin_city: mf(p.origin), founded_year: mf(p.founded), why_miss: mf(p.kind === 'item' ? p.why : null), contents: mf(p.contents.join('\n')), shipping_note: mf(null), ingredients: mf(null) },
      reviews: { rating: mf(null), rating_count: 0 },
    },
  };
}
const products = catalog.map(toProduct);
const boxes = products.filter((p) => p.tags.includes('gift-box'));
const items = products.filter((p) => !p.tags.includes('gift-box'));
const byTag = (t) => items.filter((p) => p.tags.includes(t));
const col = (title, list, extra = {}) => ({ title, url: 'collection.html', handle: title.toLowerCase(), products: list, products_count: list.length, description: '', featured_image: null, filters: [], sort_options: [{ value: 'manual', name: 'Featured' }, { value: 'best-selling', name: 'Best selling' }, { value: 'price-ascending', name: 'Price, low to high' }], sort_by: 'manual', default_sort_by: 'manual', metafields: { custom: { kicker: mf(null), seo_copy: mf(null) } }, ...extra });

const collections = {
  all: col('Shop all', items, { description: '<p>Every Michigan-only classic we carry: chips, pop, sweets, Up North pantry and U.P. treats.</p>', metafields: { custom: { kicker: mf('the whole Mitten, one aisle'), seo_copy: mf(null) } } }),
  bestsellers: col('Bestsellers', byTag('bestseller')),
  boxEligible: col('Box items', byTag('box-eligible')),
};

const boxBuilder = { id: 9000, title: 'Build Your Own Michigan Box', variants: [
  { id: 9101, title: 'Small', price: 600, available: true }, { id: 9102, title: 'Classic', price: 800, available: true }, { id: 9103, title: 'Big', price: 1200, available: true }] };

const cart = (() => {
  const lines = [products.find((p) => p.handle.startsWith('the-up-north')), items[0], items.find((p) => p.handle.startsWith('vernors'))];
  const its = lines.map((p, i) => ({ key: 'k' + i, product: p, product_id: p.id, url: p.url, image: p.featured_media, quantity: i === 1 ? 2 : 1, variant: p.selected_or_first_available_variant, properties: {}, line_level_discount_allocations: [], final_line_price: p.price * (i === 1 ? 2 : 1), original_line_price: p.price * (i === 1 ? 2 : 1) }));
  const total = its.reduce((a, b) => a + b.final_line_price, 0);
  return { items: its, item_count: its.reduce((a, b) => a + b.quantity, 0), total_price: total, attributes: {}, currency: { iso_code: 'USD' }, cart_level_discount_applications: [] };
})();

const L = (title, url, links = []) => ({ title, url, links, active: false, current: false });
const linklists = {
  'main-menu': { title: 'Main menu', links: [
    L('Gift boxes', 'collection.html', [L('All gift boxes', 'collection.html'), L('Under $50', 'collection.html'), L('$50–$100', 'collection.html'), L('$100 & up', 'collection.html'), L('Corporate gifts', 'corporate.html')]),
    L('Shop the Mitten', 'collection.html', [L('Chips & Snacks', 'collection.html'), L('Michigan Pop', 'collection.html'), L('Fudge & Sweets', 'collection.html'), L('Up North Cherries', 'collection.html'), L('Pantry & Sauces', 'collection.html'), L('Coffee & Breakfast', 'collection.html')]),
    L('By region', 'collection.html', [L('Metro Detroit', 'collection.html'), L('West Michigan', 'collection.html'), L('Up North', 'collection.html'), L('The U.P.', 'collection.html'), L('The Thumb', 'collection.html')]),
    L('Build a Box', 'build-a-box.html'), L('Corporate', 'corporate.html')] },
  'footer-shop': { title: 'Shop', links: [L('Michigan gift boxes', '#'), L('Michigan care packages', '#'), L('Gifts under $50', '#'), L('Build a box', '#'), L('Corporate gifts', '#')] },
  'footer-help': { title: 'Help', links: [L('Shipping & deadlines', '#'), L('FAQ', '#'), L('Contact', '#'), L('Refund policy', '#')] },
  footer: { title: 'The Mitten', links: [L('Our story', '#'), L('Foods you can only get in Michigan', '#'), L('Where to buy Vernors outside Michigan', '#'), L('Detroit Gift Store ↗', 'https://detroitgiftstore.com')] },
  'collection-chips': { title: 'Chips', links: [L('All', '#'), L('Under $25', '#'), L('Under $50', '#'), L('Metro Detroit', '#'), L('Up North', '#'), L('The U.P.', '#'), L('Pop', '#'), L('Ships free', '#')] },
};

/* ---------------- engine ---------------- */
const engine = new Liquid({ root: [path.join(THEME, 'snippets')], extname: '.liquid', strictFilters: false, strictVariables: false, jsTruthy: false });

engine.registerTag('schema', class extends Tag { constructor(t, r, l) { super(t, r, l); while (r.length) { const x = r.shift(); if (x.name === 'endschema') break; } } * render() {} });
engine.registerTag('layout', class extends Tag { * render() {} });

engine.registerTag('form', class extends Tag {
  constructor(token, remain, liquid) {
    super(token, remain, liquid);
    this.args = token.args; this.tpls = [];
    const stream = liquid.parser.parseStream(remain).on('tag:endform', () => stream.stop()).on('template', (t) => this.tpls.push(t)).on('end', () => { throw new Error('form not closed'); });
    stream.start();
  }
  * render(ctx, emitter) {
    const m = this.args.match(/\bid:\s*([^,]+)/);
    const id = m ? yield this.liquid.evalValue(m[1].trim(), ctx) : '';
    const cls = (this.args.match(/class:\s*'([^']+)'/) || [])[1] || '';
    const data = /data-product-form/.test(this.args) ? ' data-product-form' : '';
    emitter.write(`<form method="post" action="#"${id ? ` id="${id}"` : ''}${cls ? ` class="${cls}"` : ''}${data}>`);
    ctx.push({ form: { posted_successfully: false, errors: null } });
    yield this.liquid.renderer.renderTemplates(this.tpls, ctx, emitter);
    ctx.pop();
    emitter.write('</form>');
  }
});

engine.registerTag('paginate', class extends Tag {
  constructor(token, remain, liquid) {
    super(token, remain, liquid); this.tpls = [];
    const stream = liquid.parser.parseStream(remain).on('tag:endpaginate', () => stream.stop()).on('template', (t) => this.tpls.push(t)).on('end', () => { throw new Error('paginate not closed'); });
    stream.start();
  }
  * render(ctx, emitter) {
    ctx.push({ paginate: { pages: 1, parts: [], current_page: 1 } });
    yield this.liquid.renderer.renderTemplates(this.tpls, ctx, emitter);
    ctx.pop();
  }
});

async function renderSection(type, data, ctx, idOverride) {
  const src = read(`sections/${type}.liquid`);
  const schema = schemaOf(src);
  const defaults = Object.fromEntries((schema.settings || []).filter((s) => s.id).map((s) => [s.id, s.default ?? null]));
  const settings = Object.fromEntries(Object.entries({ ...defaults, ...(data?.settings || {}) }).map(([k, v]) => [k, fixUrl(v)]));
  let blocks = [];
  if (data?.block_order) {
    blocks = data.block_order.map((bid) => {
      const b = data.blocks[bid];
      const bs = (schema.blocks || []).find((x) => x.type === b.type) || {};
      const bdef = Object.fromEntries((bs.settings || []).filter((s) => s.id).map((s) => [s.id, s.default ?? null]));
      const st = Object.fromEntries(Object.entries({ ...bdef, ...(b.settings || {}) }).map(([k, v]) => [k, fixUrl(v)]));
      return { id: bid, type: b.type, settings: st, shopify_attributes: '' };
    });
  }
  const id = idOverride || type;
  (ctx.overrides?.[type] || (() => {}))(settings, blocks);
  const html = await engine.parseAndRender(src, { ...ctx, section: { id, settings, blocks } }, { globals: ctx });
  return `<div id="shopify-section-${id}" class="shopify-section">${html}</div>`;
}

async function renderJsonTemplate(file, ctx) {
  const tpl = JSON.parse(read(file));
  let out = '';
  for (const key of tpl.order) {
    const s = tpl.sections[key];
    if (s.disabled) continue;
    out += await renderSection(s.type, s, ctx, key);
  }
  return out;
}

async function page(outName, templateFile, extra = {}) {
  const settings = JSON.parse(read('config/settings_data.json')).presets.Default;
  const ctx = {
    settings: { ...settings, logo: null, favicon: null, share_image: null, melt_notice: 'Chocolate & fudge ship with ice packs May–September.' },
    shop: { name: 'Michigan Gift Store', money_format: '${{amount}}', customer_accounts_enabled: true, description: 'Michigan-only snacks, pop and sweets, shipped home.', enabled_payment_types: [], url: 'index.html' },
    routes: { root_url: 'index.html', cart_url: 'cart.html', cart_add_url: '/cart/add', cart_change_url: '/cart/change', cart_update_url: '/cart/update', search_url: '#', account_url: '#', all_products_collection_url: 'collection.html', product_recommendations_url: '#' },
    request: { locale: { iso_code: 'en' }, page_type: extra.page_type || 'index', origin: 'https://michigangiftstore.com' },
    template: { name: extra.page_type || 'index', suffix: extra.suffix || null },
    canonical_url: 'https://michigangiftstore.com/', page_title: extra.title || 'Michigan Gifts & Gift Boxes, Shipped Home', page_description: 'Better Made, Faygo, Vernors, Sanders and more: Michigan-only classics shipped to all 50 states.',
    cart, linklists, collections: [], content_for_header: '', current_page: 1,
    ...extra,
  };
  const layoutSrc = read('layout/theme.liquid');
  const content = await renderJsonTemplate(templateFile, ctx);
  // layout: swap in sections groups + content manually, then render the rest.
  const header = await renderJsonGroup('sections/header-group.json', ctx);
  const footer = await renderJsonGroup('sections/footer-group.json', ctx);
  const drawer = await renderSection('cart-drawer', { settings: {} }, { ...ctx, overrides: { 'cart-drawer': (s) => { s.upsell_collection = collections.boxEligible; } } });
  // Render the layout shell; pre-rendered sections are swapped in after so they aren't re-parsed.
  const tokens = [];
  const marker = (s) => { tokens.push(s); return `@@SEC${tokens.length - 1}@@`; };
  const shell = layoutSrc
    .replace("{% sections 'header-group' %}", () => marker(header))
    .replace("{% sections 'footer-group' %}", () => marker(footer))
    .replace("{% section 'cart-drawer' %}", () => marker(drawer))
    .replace('{{ content_for_layout }}', () => marker(content));
  let html = await engine.parseAndRender(shell, ctx, { globals: ctx });
  html = html.replace(/@@SEC(\d+)@@/g, (_, i) => tokens[Number(i)]);
  // Static preview: stub cart endpoints so quick-add opens the drawer instead of erroring.
  html = html.replace('</head>', `<script>(function(){var f=window.fetch;window.fetch=function(u,o){u=String(u);if(/cart\\/(add|change|update)\\.js|cart\\.js|^#/.test(u)){return Promise.resolve(new Response(JSON.stringify({item_count:${cart.item_count},sections:null}),{status:200,headers:{'Content-Type':'application/json'}}));}return f.apply(this,arguments);};})();</script></head>`);
  fs.writeFileSync(path.join(DIST, outName), html);
  console.log('wrote', outName, (html.length / 1024).toFixed(0) + 'KB');
}

async function renderJsonGroup(file, ctx) {
  const g = JSON.parse(read(file));
  let out = '';
  for (const key of g.order) out += await renderSection(g.sections[key].type, g.sections[key], ctx, key);
  return out;
}

/* ---------------- filters ---------------- */
engine.registerFilter('t', (key, ...args) => {
  let v = key.split('.').reduce((o, k) => (o ? o[k] : undefined), locale);
  if (typeof v !== 'string') return key;
  for (const [k, val] of Object.entries(kw(args))) v = v.replaceAll(`{{ ${k} }}`, val);
  return v;
});
engine.registerFilter('money', moneyFmt);
engine.registerFilter('money_without_trailing_zeros', (c) => moneyFmt(c).replace(/\.00$/, ''));
engine.registerFilter('money_without_currency', (c) => (Number(c || 0) / 100).toFixed(2));
engine.registerFilter('image_url', (m) => (m && typeof m === 'object' ? m.src : m));
engine.registerFilter('image_tag', (src, ...args) => {
  const a = kw(args); const attrs = [];
  for (const [k, v] of Object.entries(a)) if (!['widths', 'sizes'].includes(k)) attrs.push(v === '' ? k : `${k}="${String(v).replace(/"/g, '&quot;')}"`);
  if (!('alt' in a)) attrs.push('alt=""');
  return `<img src="${src}" ${attrs.join(' ')} width="800" height="800">`;
});
engine.registerFilter('placeholder_svg_tag', (_n, cls) => `<svg class="${cls || ''}" viewBox="0 0 100 100" preserveAspectRatio="xMidYMid slice"><rect width="100" height="100" fill="#E9E2D2"/><path d="M30 70l15-20 10 12 8-9 12 17z" fill="#D6CDB8"/><circle cx="64" cy="36" r="6" fill="#D6CDB8"/></svg>`);
engine.registerFilter('asset_url', (f) => `assets/${f}`);
engine.registerFilter('shopify_asset_url', (f) => `#${f}`);
engine.registerFilter('stylesheet_tag', (u) => `<link rel="stylesheet" href="${u}">`);
engine.registerFilter('preload_tag', (u) => `<link rel="preload" href="${u}" as="font" type="font/woff2" crossorigin>`);
engine.registerFilter('color_mix', (a, b, pct) => { const x = hexToRgb(a), y = hexToRgb(b); const p = Number(pct) / 100; return rgbToHex(x.map((v, i) => v * p + y[i] * (1 - p))); });
engine.registerFilter('color_darken', (a, pct) => rgbToHex(hexToRgb(a).map((v) => v * (1 - Number(pct) / 100))));
for (const f of ['payment_terms', 'payment_button', 'payment_type_svg_tag', 'default_errors', 'structured_data', 'default_pagination']) engine.registerFilter(f, () => '');
engine.registerFilter('metafield_tag', (m) => (m && m.value) || '');
engine.registerFilter('format_code', (c) => c);

/* ---------------- pages ---------------- */
fs.rmSync(DIST, { recursive: true, force: true });
fs.mkdirSync(path.join(DIST, 'assets'), { recursive: true });
for (const f of fs.readdirSync(path.join(THEME, 'assets'))) fs.copyFileSync(path.join(THEME, 'assets', f), path.join(DIST, 'assets', f));

const tierOverride = (s, blocks) => blocks.forEach((b, i) => { b.settings.product = boxes[i]; });
const homeOverrides = {
  'gift-box-tiers': tierOverride,
  'featured-collection': (s) => { s.collection = collections.bestsellers; },
  'collection-tiles': (s, blocks) => blocks.forEach((b) => { b.settings.collection = { url: 'collection.html', products_count: 0 }; }),
  'miss-quiz': (s, blocks) => blocks.forEach((b) => { b.settings.collection = { url: 'collection.html' }; }),
  'region-map': (s, blocks) => blocks.forEach((b) => { b.settings.collection = { url: 'collection.html' }; }),
};

const upNorth = products.find((p) => p.handle.startsWith('the-up-north'));
const bbq = products.find((p) => p.handle.startsWith('better-made-special-bbq'));

await page('index.html', 'templates/index.json', { overrides: homeOverrides });
await page('product.html', 'templates/product.json', { page_type: 'product', product: upNorth, title: upNorth.title, overrides: {} });
await page('product-item.html', 'templates/product.json', { page_type: 'product', product: bbq, title: bbq.title, overrides: {} });
await page('collection.html', 'templates/collection.json', { page_type: 'collection', collection: collections.all, title: 'Shop all', overrides: {} });
await page('build-a-box.html', 'templates/page.build-a-box.json', { page_type: 'page', suffix: 'build-a-box', title: 'Build a box', overrides: { 'build-a-box': (s) => { s.box_product = boxBuilder; s.collection = collections.boxEligible; } } });
await page('corporate.html', 'templates/page.corporate-gifts.json', { page_type: 'page', suffix: 'corporate-gifts', title: 'Corporate gifts', overrides: { 'gift-box-tiers': tierOverride } });
await page('cart.html', 'templates/cart.json', { page_type: 'cart', title: 'Your box', overrides: { 'featured-collection': (s) => { s.collection = collections.bestsellers; } } });
await page('faq.html', 'templates/page.faq.json', { page_type: 'page', suffix: 'faq', title: 'FAQ', overrides: {} });
await page('404.html', 'templates/404.json', { page_type: '404', title: 'Not found', overrides: {} });
